"use strict";const container=document.querySelector(".fireworks");if(container&&"undefined"!=typeof Fireworks&&Fireworks.default){new Fireworks.default(container).start()}function scrollToElement(e,o){setTimeout(function(){const o=document.getElementById(e);o?o.scrollIntoView({behavior:"smooth",block:"center"}):console.error("Element with id '"+e+"' not found.")},1e3*o)}scrollToElement("scroll",3);